{
  "title": "Does button B sell more?",
  "setting": "Day 3 at Aurora Shop",
  "mission": "Decide whether the new checkout button actually increases sales or if the difference is random noise. **Determine if we have enough data to launch.**",
  "deadline": "Meeting with leadership today at 3:00 p.m.",
  "panels": [
    {
      "title": "A/B Test Results (Day 1)",
      "metrics": [
        {
          "label": "Version A Conversion",
          "value": "3.2%",
          "note": "1,200 visits"
        },
        {
          "label": "Version B Conversion",
          "value": "3.8%",
          "note": "1,200 visits"
        }
      ],
      "note": "Live for 1 day across all mobile users."
    }
  ],
  "team": [
    {
      "id": "product",
      "role": "Product Manager",
      "expertise": "Wants to launch the new checkout button immediately to boost sales.",
      "ai": false
    },
    {
      "id": "analyst",
      "role": "Senior Data Analyst",
      "expertise": "Cautious about statistical significance and sample sizes.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "Analytics AI",
      "expertise": "Runs statistical checks and calculates p-values when asked.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a wrong call",
      "start": 60,
      "goodWhen": "low"
    },
    {
      "id": "patience",
      "label": "{{product}}'s patience",
      "start": 70,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "diff",
      "name": "Tell a real difference from chance",
      "practice": "Check whether a small conversion difference could be explained by random chance."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Calculate how many more visitors an A/B test needs before making a call."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain a p-value to a non-data colleague in one simple sentence."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "Version B is already showing a 0.6% bump in sales after just one day. We should roll it out to everyone now!"
        },
        {
          "from": "analyst",
          "text": "Hold on, {{product}}. One day isn't enough time, and our sample size is way too small to be sure this isn't just luck."
        }
      ],
      "prompt": "How do you handle the early test results?",
      "choices": [
        {
          "id": "ask-ai",
          "text": "Ask {{ai}} to run a statistical significance test on the current visitor data.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I ran the check. The p-value is 0.24, which means there's a 24% chance this result is just random noise."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "patience",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "diff",
              "kind": "good",
              "text": "You checked for statistical significance instead of trusting early numbers.",
              "example": null
            }
          ],
          "next": "interpret-data"
        },
        {
          "id": "wait-more",
          "text": "Tell {{product}} we need to wait another week to gather more data before deciding.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "A whole week? That's going to delay our quarterly targets, but fine, let's wait a bit longer."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "patience",
              "change": -25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You recognized the need for a larger sample size, though it tested {{product}}'s patience.",
              "example": null
            }
          ],
          "next": "extended-test"
        },
        {
          "id": "launch-now",
          "text": "Agree with {{product}} and ship Version B to all users immediately.",
          "quality": "weak",
          "replies": [
            {
              "from": "analyst",
              "text": "I really think we're rushing this. I hope luck is on our side."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 30
            },
            {
              "meter": "patience",
              "change": 20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "diff",
              "kind": "improve",
              "text": "You made a call based on a tiny sample where random chance easily could be the cause.",
              "example": "Let's check if this difference is real before rolling it out to everyone."
            }
          ],
          "next": "rushed-ending"
        }
      ]
    },
    {
      "id": "interpret-data",
      "messages": [
        {
          "from": "analyst",
          "text": "See? A p-value of 0.24 is way above our 0.05 threshold. We can't claim Version B wins yet."
        },
        {
          "from": "product",
          "text": "So what do we tell the team? Should we keep running the test or scrap it?"
        }
      ],
      "prompt": "How do you explain the situation to {{product}} and decide the next step?",
      "choices": [
        {
          "id": "explain-clear",
          "text": "Explain to {{product}} in simple terms that the current gap could easily happen by chance, and propose running it for 5 more days.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Got it. So it's like flipping a coin a few times and getting heads twice in a row. Let's run it longer."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": {
            "label": "Five days later",
            "panel": {
              "title": "A/B Test Results (Day 6)",
              "metrics": [
                {
                  "label": "Version A Conversion",
                  "value": "3.3%",
                  "note": "7,500 visits"
                },
                {
                  "label": "Version B Conversion",
                  "value": "3.7%",
                  "note": "7,500 visits"
                }
              ],
              "note": "Sufficient sample size reached."
            }
          },
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You explained the statistical concept clearly without using heavy jargon.",
              "example": null
            }
          ],
          "next": "final-call"
        },
        {
          "id": "jargon-push",
          "text": "Tell {{product}} the p-value is too high and reject the null hypothesis failure.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I have no idea what null hypothesis means. Can we just launch or not?"
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 10
            },
            {
              "meter": "patience",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Using raw statistical jargon confused your colleague instead of helping them understand.",
              "example": "The current data difference is too small to prove Version B is truly better yet."
            }
          ],
          "next": "rushed-ending"
        }
      ]
    },
    {
      "id": "extended-test",
      "messages": [
        {
          "from": "analyst",
          "text": "We have enough traffic now. Let's look at the final numbers."
        }
      ],
      "prompt": "The extended test is complete. What is your final call?",
      "choices": [
        {
          "id": "ship-safe",
          "text": "Review the p-value of 0.03 with {{analyst}} and safely roll out Version B.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Fantastic! Thanks for being thorough and patient with this."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "diff",
              "kind": "good",
              "text": "You waited for sufficient sample size and verified the result against chance.",
              "example": null
            }
          ],
          "next": "success-ending"
        },
        {
          "id": "cancel-test",
          "text": "Play it ultra-safe and keep Version A since the improvement wasn't massive.",
          "quality": "fair",
          "replies": [
            {
              "from": "analyst",
              "text": "Even with a real difference, staying put is safe, though we miss a small gain."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "You were overly cautious even after gathering enough data.",
              "example": null
            }
          ],
          "next": "cautious-ending"
        }
      ]
    },
    {
      "id": "final-call",
      "messages": [
        {
          "from": "ai",
          "text": "The 6-day sample is complete. P-value is now 0.02."
        }
      ],
      "prompt": "Make your final decision based on the updated sample.",
      "choices": [
        {
          "id": "launch-winner",
          "text": "Approve the rollout of Version B based on the statistically significant result.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Woohoo! Our patience paid off."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "diff",
              "kind": "good",
              "text": "You successfully combined sufficient sample size with correct significance testing.",
              "example": null
            }
          ],
          "next": "success-ending"
        },
        {
          "id": "hesitate",
          "text": "Hesitate and decide to run the test for another week just to be safe.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Another week? We already have clear statistical significance!"
            }
          ],
          "effects": [
            {
              "meter": "patience",
              "change": -30
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Avoid over-testing when you already have sufficient sample size and clear significance.",
              "example": null
            }
          ],
          "next": "cautious-ending"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "success-ending",
      "outcome": "Version B was successfully rolled out after confirming statistical significance with enough data. Purchases increased by 15% overall."
    },
    {
      "id": "cautious-ending",
      "outcome": "The test concluded safely, avoiding any false alarms, though some potential upside was delayed by extra caution."
    },
    {
      "id": "rushed-ending",
      "outcome": "Rushing the launch without verifying significance led to unstable metrics, and the expected sales boost disappeared within a week."
    }
  ],
  "summary": [
    "Distinguish real performance differences from random chance using statistical significance.",
    "Ensure adequate sample sizes before making high-stakes business decisions.",
    "Communicate complex test results clearly to colleagues without relying on confusing jargon."
  ]
}

{
  "title": "E se a luz viesse em pacotes?",
