  "startNodeId": "decisao-1",
  "nodes": [
    {
      "id": "decisao-1",
      "messages": [
        {
          "from": "ana",
          "text": "{{joao}} tentou acender a lâmpada com um dimmer contínuo, mas nada aconteceu até passarmos do limite mínimo!"
